\label{thm:adequate-boundary}
Let $\pi: \mathscr X \to X$ be an adequate moduli space. Let $i: \mathscr D \hookrightarrow \mathscr X$ be a reduced effective Cartier divisor on $\mathscr X$ with normal bundle $\mathcal N:=\mathcal N_{\mathscr D/\mathscr X}=\mathcal O_{\mathscr X}(\mathscr D)|_\mathscr D$. Then the following are equivalent:
\begin{enumerate}
\item 
the closed substack $\mathscr D \subseteq \mathscr X$ is removable for $\pi$.
\item 
the canonical map $\mathcal O_X \to \pi_*\mathcal O_{\mathscr X}(n\mathscr D)$ is an isomorphism for every integer $n > 0$.
\item
the condition $(\pi \circ i)_*\mathcal N^{\otimes n}=0$ holds for every integer $n>0$.
\end{enumerate}

\label{rmk:ev1-closed-immersion}
If $X$ is separated, the evaluation map $\operatorname{ev}_1$ is a monomorphism \cite[Prop. 1.4.11]{Drinfeld}, but in general not a locally closed immersion, even restricted to connected components of $X_\lambda^+$ \cite[Ex. 1.4.12]{Drinfeld}. However, the restriction of $\operatorname{ev}_1$ to each connected component of $X_\lambda^+$ is a locally closed immersion if $X$ is smooth \cite[Thm. B.0.3 (i)]{Drinfeld}. 

If the quotient stack $[X/G]$ is $\Theta$-reductive (e.g., if $X$ admits a good quotient $X \to X/G$), then $\operatorname{ev}_1: X_\lambda^+ \to X$ is a closed immersion \cite[Prop. 3.13 and Rmk. 3.14]{AHLH}. In particular, for any $\lambda \in X_*(G)$ and $F \in \pi_0(X_\lambda)$, the restriction $\operatorname{ev}_1: C_{\lambda,F} \to X$ is a closed immersion, and in this case we identify $C_{\lambda,F}$ with a closed subscheme of $X$ via $\operatorname{ev}_1$, and it sits inside
\[
\begin{tikzcd}
C_{\lambda,F} \ar[r,hook] \ar[d] & X_\lambda^+ \ar[r,hook,"\operatorname{ev}_1"] \ar[d,"\operatorname{ev}_0"] & X \\
F \ar[r,hook] \ar[u,bend left,"\iota"] & X_\lambda \ar[u,bend left,"\iota"]
\end{tikzcd}
\]

\label{lem:theta-weight}
Let $K$ be a field, and let $\mathcal L$ be a $\mathbb{G}_{m,K}$-equivariant line bundle on $\mathbb A^1_K$. Then
\[
\Gamma(\Theta_K,\mathcal L)=\Gamma(\mathbb A^1_K,\mathcal L)^{\mathbb{G}_{m,K}}=
\begin{cases}
0 & \text{if } \operatorname{wt}(\mathcal L) < 0 \\
K \cdot a^{d}e & \text{if } \operatorname{wt}(\mathcal L)=d \geq 0
\end{cases}
\]
where $\mathbb A^1_K=\operatorname{Spec} K[a]$ and $e$ is the unique (up to a non-zero scalar) non-vanishing section of $\mathcal L$. In particular, there exists a non-zero section of $\mathcal L$ vanishing at $0$ only if $\operatorname{wt}(\mathcal L)>0$.

\label{cor:weight-inclusion}
Let $k$ be a field, let $G$ be an affine algebraic group over $k$, and let $X$ be a $k$-scheme with a $G$-action. Let $D$ be a $G$-invariant effective Cartier divisor on $X$ and $\mathcal L:=\mathcal O_X(D)$. For any $\lambda \in X_*(G)$ and $F \in \pi_0(X_\lambda)$, we have
\begin{enumerate}
\item 
If $\operatorname{wt}_\lambda(\mathcal L|_F)<0$, then $G.C_{\lambda,F} \subseteq D$.
\item 
If $D \cap F = \varnothing$, then $\operatorname{wt}_{\lambda}(\mathcal L|_F) = 0$.
\end{enumerate}

\label{lem:lifting-Theta}
Consider a Cartesian diagram
\[
\begin{tikzcd}
\mathscr Y \ar[r] \ar[d] & \mathscr X \ar[d] \\
\mathscr Z \ar[r] & X
\end{tikzcd}
\]
where $\mathscr X,\mathscr Y,\mathscr Z$ are algebraic stacks and $X$ is an algebraic space. A morphism $f: \Theta \to \mathscr X$ lifts to $\mathscr Y$ if and only if $f(1) \in \mathscr X$ lifts to $\mathscr Y$.

\label{thm:quotient-boundary}
Assume the hypotheses of  \Cref{setup:quotient}. Let $D$ be a $G$-invariant reduced effective Cartier divisor on $X$ and $\mathcal L:=\mathcal O_X(D)$. Then $D \subseteq X$ is removable for $\pi$ if and only if
\begin{equation}\label{eq:character-D}
D = \bigcup_{\operatorname{wt}_\lambda(\mathcal L|_F)<0} G.C_{\lambda,F}.
\end{equation}
In particular, if $D$ is irreducible, then $D \subseteq X$ is removable for $\pi$ if and only if
\[
D = G.C_{\lambda,F} \text{ with } \operatorname{wt}_\lambda(\mathcal L|_F)<0.
\]

\label{thm:main-Gm}
Let $k$ be an algebraically closed field, and let $X$ be a smooth $k$-variety with a ${\mathbb{G}_m}$-action. Suppose that $X$ admits a good quotient $q: X \to X/{\mathbb{G}_m}$. Then the assignment $(\sigma^+,\sigma^-) \mapsto X \setminus \cup_{i \in \sigma^\pm} X_i^\pm$ defines a bijection between
\[
\left\{ 
(\sigma^+,\sigma^-): \sigma^\pm \subseteq \mathrm{PD}^\pm, \sigma^+ \cap \sigma^-=\varnothing 
\right\} 
\xleftrightarrow{1:1} \operatorname{Op}(q).
\]

\label{prop:chart-test}
Let $\pi: \mathscr X \to X$ be an adequate moduli space. Suppose that there is an \'{e}tale cover $\{X_i \to X\}_i$ of $X$ by affine schemes, and over each $X_i$ an isomorphism
\[
\mathscr X \times_X X_i \simeq [V_i/G_i],
\]
where $V_i \to X_i$ is affine and $G_i \to X_i$ is a reductive group scheme. For an open substack $\mathscr U \subseteq \mathscr X$, let $W_i:=\mathscr U \times_{\mathscr X} V_i \subseteq V_i$. Then $\mathscr U$ preserves $\pi$ if and only if
\begin{equation}\label{eq:chart-test}
W_i \text{ is affine, and } \Gamma(V_i,\mathcal O_{V_i})^{G_i} \xrightarrow{\sim} \Gamma(W_i,\mathcal O_{W_i})^{G_i} \text{ for each } i.
\end{equation}
Conversely, a family of $G_i$-invariant open subsets $W_i \subseteq V_i$ satisfying \eqref{eq:chart-test} uniquely determines an open substack of $\mathscr X$ preserving $\pi$, provided these open subsets $W_i \subseteq V_i$ agree after pullback to each $V_i \times_{\mathscr X} V_j$.

\label{lem:adequate-charts}
Let $\mathscr X$ be a locally reductive algebraic stack with separated diagonal. Suppose that there is an adequate moduli space $\pi: \mathscr X \to X$. There is an \'{e}tale cover $\{\operatorname{Spec} B_i \to X\}_i$ of $X$ by affine schemes and Cartesian diagrams
\[
\begin{tikzcd}
\left[ \operatorname{Spec} A_i/\operatorname{GL}_{n_i} \right] \ar[r] \ar[d,"\pi_i"'] & \mathscr X \ar[d,"\pi"] \\
\operatorname{Spec} B_i \ar[r] & X
\end{tikzcd}
\]
where $\pi_i$ is an adequate moduli space, i.e., $A_i^{\operatorname{GL}_{n_i}} = B_i$. If $\mathscr X$ is quasi-compact, the \'{e}tale cover of $X$ can be chosen finite.

\label{setup:locally-reductive}
Let $k$ be an algebraically closed field, let $\mathscr X$ be a locally reductive algebraic stack of finite type over $k$ with separated
diagonal, and let $\pi: \mathscr X \to X$ be an adequate moduli space.

\label{thm:geometric-good}
Assume the hypotheses of \Cref{setup:locally-reductive}. Let $\mathscr D$ be a reduced effective Cartier divisor on $\mathscr X$ and $\mathcal L:=\mathcal O_{\mathscr X}(\mathscr D)$.
Then $\mathscr D \subseteq \mathscr X$ is removable for $\pi$ if and only if
\begin{equation}\label{eq:description-in-locally-reductive}
\mathscr D = \bigcup_{Z \in \pi_0(\operatorname{Grad}(\mathscr X)), \operatorname{wt}(\mathcal L|_Z)<0} \mathscr A_Z.
\end{equation}
In particular, if $\mathscr D$ is irreducible, then $\mathscr D \subseteq \mathscr X$ is removable for $\pi$ if and only if 
\[
\mathscr D = \mathscr A_Z \text{ with } \operatorname{wt}(\mathcal L|_Z)<0.
\]
